function g({registerIndicator:b,nulls:y}){b({id:"oa-vr",name:"Volatility Ratio (VR)",category:"Volatility",placement:"pane",inputs:[{key:"atrPeriod",type:"number",label:"ATR Period",default:14,min:1,max:5e3,step:1,tooltip:"The lookback period for calculating the Average True Range (ATR)."}],plots:[{key:"vr",type:"line",title:"VR",style:{color:"#ffeb3b",lineWidth:2}}],calc(a,A){const l=Math.max(1,Math.floor(Number(A.atrPeriod)||14)),u=a.length,m=new Array(u).fill(NaN),F=1e-10,R=1/l;let i=0,n=NaN,r=1;for(let e=0;e<u;e++){const f=a[e].high,h=a[e].low,s=e>0?a[e-1].close:void 0,d=f-h;let t;Number.isFinite(s)?t=Math.max(d,Math.abs(f-s),Math.abs(h-s)):t=d;const p=Number.isFinite(t)?t:0;!Number.isFinite(n)&&r===1?i=p:i=((Number.isFinite(n)?n:0)*(l-1)+p)/l,r=(1-R)*r;const N=1-r;let o;if(r>F&&N!==0?o=i/N:o=i,Number.isFinite(t)&&Number.isFinite(o)&&o!==0){const c=t/o;Number.isFinite(c)&&(m[e]=c)}n=i}return{vr:y(m)}}})}export{g as default};
